splay: flex; align-items: center; gap: 8px; margin-top: 18px; }.ad-overview-share code { flex: 1 1 0%; min-width: 0px; height: 36px; padding: 9px 11px; overflow: hidden; background: var(--ad-wash); border: 1px solid var(--ad-line); border-radius: 8px; color: var(--ad-ink-3); font: 12px/1.35 var(--ad-mono); text-overflow: ellipsis; white-space: nowrap; }.ad-overview-toggle-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; }.ad-overview-toggle-row b { display: block; font-size: 13px; }.ad-overview-cli { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 30px 28px; min-height: 140px; box-sizing: border-box; background: url("/replays/assets/6079487309dc.svg") center center / cover no-repeat rgb(11, 41, 54); border-color: rgb(23, 61, 76); box-shadow: rgba(7, 28, 35, 0.12) 0px 6px 18px; }.ad-overview-cli h3 { margin: 0px 0px 10px; color: rgb(255, 255, 255); font-size: 22px; font-weight: 600; }.ad-overview-cli p { margin: 0px; max-width: 620px; color: rgb(255, 255, 255); font-size: 14px; line-height: 1.6; }.ad-overview-cli-btn { flex: 0 0 auto; padding: 10px 16px; border: 1px solid rgb(255, 255, 255); border-radius: 8px; background: rgb(255, 255, 255); color: rgb(16, 42, 55); font-family: inherit; font-size: 13px; font-weight: 600; white-space: nowrap; cursor: pointer; box-shadow: rgba(0, 0, 0, 0.08) 0px 2px 6px; }.ad-overview-cli-btn:hover { background: rgb(234, 242, 246); border-color: rgb(234, 242, 246); }@media (max-width: 1180px) {
